auto func (auto value){  
    bool isIntegral = is_integral_v<decltype(value)>;  
    int count = 0;  
    for(auto& ch : value) {  
        if(isalpha(ch)) ++count;  
    }  
    return make_tuple(isIntegral, count == value.size(), count);  
}

